using Shop;

var builder = WebApplication.CreateBuilder(args);
// BUG: Transient lifetime - every request (in fact every resolution) gets a
// brand-new empty CartRepository, so nothing persists: every added item has
// id 1 and GET /cart is always empty.
builder.Services.AddTransient<CartRepository>();
var app = builder.Build();

app.MapPost("/cart", (AddItemRequest req, CartRepository repo) =>
    Results.Created("/cart", repo.Add(req.name)));

app.MapGet("/cart", (CartRepository repo) => Results.Ok(repo.List()));

app.Run();

public record AddItemRequest(string name);

