using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class CartTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public CartTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private record ItemDto(int id, string name);

    [Fact]
    public async Task ItemsPersistAcrossRequests()
    {
        var client = _factory.CreateClient();

        var first = await (await client.PostAsJsonAsync("/cart", new { name = "hammer" }))
            .Content.ReadFromJsonAsync<ItemDto>();
        Assert.Equal(1, first!.id);

        var second = await (await client.PostAsJsonAsync("/cart", new { name = "nail" }))
            .Content.ReadFromJsonAsync<ItemDto>();
        Assert.Equal(2, second!.id);   // a fresh-per-request repo would say 1 again

        var list = await (await client.GetAsync("/cart")).Content.ReadFromJsonAsync<ItemDto[]>();
        Assert.Equal(2, list!.Length);
        Assert.Equal(new[] { "hammer", "nail" }, Array.ConvertAll(list, i => i.name));
    }
}

